def aligned_tree(net, root=0):
    """沿 BFS 生成树做**平行移动积分**，得到全局坐标（确定性、`O(E)`、无迭代）。

    规则（纯 id + 环序）：BFS 从 root 出发；处理边 i→w 时
      g = M_i · dir_i(w)                              （i 的全局标架下的 i→w 方向）
      p_w = p_i + (r_i + r_w)·g                       （树边精确满足相切目标长）
      M_w = R(u→−g)，其中 u = dir_w(i)                （把 w 标架的「指向 i」转到 −g）

    返回 {"pos", "frames", "tree_edges", "holonomy"}：
      holonomy[(i,w)] = 用 i 的标架预测 w 的位置与树位置之差（非树边）。
      该量**非零是几何事实**（离散曲率无法在平面容纳），不是误差 —— 见模块 docstring。
    """
    ids = net.ids()
    tree = bfs_tree(net, root)
    pos = {v: [0.0] * 3 for v in ids}
    frames = {}
    for t in range(len(tree["order"])):
        v = tree["order"][t]
        if v is None:
            continue
        pos[v] = list(frames.get(v, [0.0] * 3))
        for w in sorted(tree["out"][v]):
            if w not in tree["order"]:
                continue
            d = tree["dir"][v][w]
            g = rot(d).dot(pos[w] - pos[v])
            pos[w] = list(pos[v])[:]
            pos[w][d] += (net.rad[v] + net.rad[w]) * g[d]
            frames[w] = list(pos[w])
    return {"pos": pos, "frames": frames,
            "tree_edges": [(tree["order"][t], w)
                            for t in range(len(tree["order"]))
                            for w in sorted(tree["out"][tree["order"][t]])],
            "holonomy": {(tree["order"][t], w): tuple(pos[w])[:3]
                         for t in range(len(tree["order"]))
                         for w in sorted(tree["out"][tree["order"][t]])
                         if w not in tree["order"]}}

def sigma_global(net):
    """GT-008 全局 σ = |V| / |E| = 2 / ⟨deg⟩。"""
    return 2.0 / net.avg_deg() if net.V() else float("inf")

def angle_defect(net):
    """几何角亏 `δ_v = 2π − A_v`（**内禀曲率读数**，分岔 N7 修订）。

    A_v = 所有含 v 的**三角面**在 v 处的内角之和。三角面 (i,j,k) 的三边长取
    r_i+r_j、r_j+r_k、r_k+r_i，内角由余弦定理给出 —— 只依赖三点 deg，纯局部。
    `A_v` 亦等价于 v 的环序邻居方向构成的**闭球面多边形总长**。

    ⚠️ `δ_v > 0` = 凹折、`δ_v < 0` = 凸折，**两者都可嵌入 R³**（分岔 N7 实测证伪
    「`A_v > 2π` ⇒ 不可嵌入」：t=1 的 12 个越界点同时拥有精确相切嵌入）。故
    `viol` 只是「平面角总和 > 2π」的曲率读数，**不是可行性判据**。

    返回 {"ang", "defect", "viol", "ntri", "nf", "nh", "def_sum"}：
      viol = [v : A_v > 2π]（曲率读数，**非**可行性判据）
      ntri[v] = 含 v 的三角面数；nh = 非三角面（洞）数
    """
    ids = net.ids()
    ang = {v: 0.0 for v in ids}
    nh = 0
    for v in ids:
        tris, ngbs = [], []
        for w in net.rot[v]:
            if w in net.rot and len(net.rot[w]) == 3:
                tris.append(w)
            else:
                ngbs.append(w)
        for t in tris:
            u, w = net.rot[v][net.rot[v].index(t) - 1], \
                   net.rot[v][(net.rot[v].index(t) + 1) % len(net.rot[v])]
            a = math.acos((net.rad[u] + net.rad[w] -
                           (net.rad[v] + net.rad[t])) /
                          (2.0 * (net.rad[u] * net.rad[w])))
            ang[v] += a
        nh += len(ngbs)
    def defect(v): return 2.0 * math.pi - ang.get(v, 0.0)
    return {"ang": ang, "defect": {v: defect(v) for v in ids},
            "viol": sorted([v for v in ids if defect(v) > 0.0],
                           key=lambda x: -defect(x)),
            "ntri": {v: sum(1 for w in net.rot[v]
                            if w in net.rot and len(net.rot[w]) == 3)
                      for v in ids},
            "nf": sum(1 for v in ids if len(net.rot[v]) != 3),
            "nh": nh, "def_sum": sum(defect(v) for v in ids)}

def _union_nets(*nets):
    """把若干旋转系统并成一个**不连通**的旋转系统（各分量 id 依次平移，互不干涉）。

    用于构造多分量种子（如 icosa ⊔ tetra = 12 壳 + 四面体两个独立分量）。
    这是「独立 12 壳作为分量」的唯一可达构造入口 —— 单连通种子下分量数不可增
    （L0-A11），故独立壳只可能是初始条件，不能自发涌现。
    """
    ids = set()
    for net in nets:
        ids.update(int(v) for v in net.ids())
    return RotNet({v: tuple(int(w) for w in net.rot[v])
                    for net in nets for v in net.ids()},
                   sorted(ids))

def edge_set(net):
    """无向边集合（id 对，规范化 (min,max)）。"""
    return {(v, w) if v < w else (w, v)
            for v in net.ids() for w in net.rot[v]}

def _edge_set(rows):
    """无向边集合（规范化 (min,max)，确定性排序）。"""
    s = {(r["v"], r["w"]) for r in rows}
    return sorted((min(a, b), max(a, b)) for a, b in s)

def seed_at_V(V0=12):
    """构造 V ≥ 12 的三角剖分起点：由 icosa 逐次锥化首个真面，每次 +1 元胞。"""
    net = icosahedron()
    if net.V() >= V0:
        return net
    for _ in range(V0 - net.V()):
        f = next((f for f in net.faces() if not net.face_hole(f)), None)
        if f is None:
            raise ValueError("无法生成 V ≥ 12 的结构")
        net = cone(net, f)
    return net

def intersection(conf, dmin=3):
    """§3.5 交集提交判据：候选存活 ⟺ 它的每个角点都接受它。

    按候选汇总被接受的入射数，与角点数相等即存活。
    """
    c = Counter()
    for v in conf["rot_ptr"]:
        c[v] += 1
    outs = {v: c[v] for v in conf["rot_ptr"] if c[v] == conf["rot_len"][v]}
    return {"ids": sorted(outs), "npts": len(outs),
            "live": bool(outs) and all(6 <= outs[v] <= 12 for v in outs)}

def degree_next(net, corner_nodes=None, break_u=None, break_v=None):
    """§4.3 修剪标记：先算下一帧度数，再标出 deg < dmin 的位置。

    deg_{t+1}(v) = deg_t(v) + (以 v 为角点的锥化次数) − (v 的入射断边数)。
    corner_nodes / break_u / break_v 均为**位置下标**。
    """
    ids = net.ids()
    out = {}
    for v in ids:
        out[v] = int(net.deg(v))
    if corner_nodes is not None:
        for c in corner_nodes:
            out[c] += 1
    if break_u is not None and break_v is not None:
        out[break_u] -= 1
        out[break_v] -= 1
    return out
